package dataStructure;

import java.util.TreeSet;

public class TreeSetExample {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//TreeSet store after sorting order
		
		TreeSet<String>objTree = new TreeSet<String>();
		objTree.add("FireFox");
		objTree.add("Brave");
		objTree.add("Edge");
		objTree.add("Chrome");
		
		System.out.println("Dispalyed TreeSet");
		System.out.println(objTree);

	}

}
